def docnew():
    doc=Document()
    sec=doc.sections[0];sec.page_width=Inches(8.5);sec.page_height=Inches(11)
    sec.left_margin=sec.right_margin=Inches(.7);sec.top_margin=sec.bottom_margin=Inches(.7)
    for sty in ['Normal','Caption','Title','Heading 1','Heading 2','Heading 3']:
        style=doc.styles[sty];style.font.name='Times New Roman';style.font.color.rgb=RGBColor.from_string('202A31')
        style.paragraph_format.space_before=Pt(0);style.paragraph_format.space_after=Pt(6)
    doc.styles['Normal'].font.size=Pt(11);doc.styles['Normal'].paragraph_format.line_spacing=1.1
    doc.styles['Title'].font.size=Pt(19);doc.styles['Title'].font.bold=True;doc.styles['Title'].paragraph_format.space_after=Pt(13)
    for sty,size in [('Heading 1',14),('Heading 2',12),('Heading 3',11)]:
        doc.styles[sty].font.size=Pt(size);doc.styles[sty].font.bold=True;doc.styles[sty].paragraph_format.space_before=Pt(10);doc.styles[sty].paragraph_format.keep_with_next=True
    for border in list(doc.styles.element.xpath('.//w:pBdr')):border.getparent().remove(border)
    doc.styles['Caption'].font.size=Pt(9.5);doc.styles['Caption'].font.italic=False;doc.styles['Caption'].font.bold=False
    doc.styles['Caption'].paragraph_format.keep_together=True;doc.styles['Caption'].paragraph_format.keep_with_next=False
    doc.styles['Caption'].paragraph_format.line_spacing=1.04
    footer=sec.footer.paragraphs[0];footer.alignment=WD_ALIGN_PARAGRAPH.CENTER
    field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');footer._p.append(field)
    doc.core_properties.title=TITLE;doc.core_properties.subject='WorldMoE, service commitments, economic bounds, publication timing and electrical delivery'
    doc.core_properties.author='';doc.core_properties.last_modified_by=''
    return doc

def para(doc,text,style='Normal'):
    p=doc.add_paragraph(style=style)
    for bit in re.split(r'(\[\[[0-9,]+\]\])',text):
        if not bit:continue
        if bit.startswith('[['):
            ids=[int(x) for x in bit[2:-2].split(',')]
            for number in ids:
                if number not in USED:USED.append(number)
            r=p.add_run(','.join(str(USED.index(n)+1) for n in ids));r.font.superscript=True;r.font.size=Pt(8)
        else:p.add_run(bit)
    return p

def heading(doc,text,level=2):return para(doc,text,f'Heading {level}')
def usd(x,dec=0):return f'{float(x):,.{dec}f}'
def perc(x,dec=2):return f'{float(x):.{dec}f}'
def public(s):return str(s).replace('Joint WorldMoE','WorldMoE').replace('original RASC-ME','RASC-ME').replace('original Seasonal-ME','Seasonal-ME')

def equation(doc,parts,label):
    if doc.paragraphs:doc.paragraphs[-1].paragraph_format.keep_with_next=True
    p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before=Pt(4);p.paragraph_format.space_after=Pt(8)
    obj=OxmlElement('m:oMath')
    def run(parent,text):
        r=OxmlElement('m:r');t=OxmlElement('m:t');t.text=text;r.append(t);parent.append(r)
    for part in parts:
        if isinstance(part,str):run(obj,part)
        else:
            kind,base,index=part;node=OxmlElement('m:sSub' if kind=='sub' else 'm:sSup');a=OxmlElement('m:e');run(a,base);node.append(a)
            b=OxmlElement('m:sub' if kind=='sub' else 'm:sup');run(b,index);node.append(b);obj.append(node)
    p._p.append(obj);p.add_run(f'     ({label})');return p

def figure(doc,stem,caption):
    p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.paragraph_format.keep_with_next=True
    p.add_run().add_picture(str(ROOT/'figures'/f'{stem}.png'),width=Inches(6.95))
    for node in p._p.xpath('.//wp:docPr'):node.set('descr',caption.split('|',1)[-1].split('.')[0].strip())
    p=doc.add_paragraph(style='Caption');p.paragraph_format.keep_together=True;p.paragraph_format.keep_with_next=False
    split=caption.index('. ',caption.index('|'))+1
    p.add_run(caption[:split]).bold=True;p.add_run(caption[split:])

def table(doc,title,headers,rows,widths=None):
    p=para(doc,title,'Caption');p.paragraph_format.keep_with_next=True
    tab=doc.add_table(rows=1,cols=len(headers));tab.autofit=False
    widths=widths or [7.0/len(headers)]*len(headers)
    for column,width in zip(tab.columns,widths):column.width=Inches(width)
    for cell,value in zip(tab.rows[0].cells,headers):cell.text=str(value)
    for row in rows:
        cells=tab.add_row().cells
        for cell,value in zip(cells,row):cell.text=str(value)
    repeat=OxmlElement('w:tblHeader');tab.rows[0]._tr.get_or_add_trPr().append(repeat)
    for i,row in enumerate(tab.rows):
        nosplit=OxmlElement('w:cantSplit');row._tr.get_or_add_trPr().append(nosplit)
        for j,cell in enumerate(row.cells):
            cell.width=Inches(widths[j]);cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            props=cell._tc.get_or_add_tcPr();shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'254C63' if i==0 else ('F1F5F7' if i%2==0 else 'FFFFFF'));props.append(shade)
            margins=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                node=OxmlElement('w:'+side);node.set(qn('w:w'),'65');node.set(qn('w:type'),'dxa');margins.append(node)
            props.append(margins)
            borders=OxmlElement('w:tcBorders')
            for side in ['top','left','bottom','right']:
                node=OxmlElement('w:'+side);node.set(qn('w:val'),'single');node.set(qn('w:sz'),'3');node.set(qn('w:color'),'D5DFE5');borders.append(node)
            props.append(borders)
            for p in cell.paragraphs:
                p.paragraph_format.space_after=Pt(2);p.paragraph_format.space_before=Pt(1);p.paragraph_format.line_spacing=1.0
                if len(rows)<=14 and i<len(tab.rows)-1:p.paragraph_format.keep_with_next=True
                if j>0:p.alignment=WD_ALIGN_PARAGRAPH.CENTER
                for r in p.runs:r.font.name='Times New Roman';r.font.size=Pt(8.6);r.font.bold=i==0;r.font.color.rgb=RGBColor.from_string('FFFFFF' if i==0 else '202A31')
    doc.add_paragraph('');return tab

