event=E['Joint WorldMoE vs original RASC-ME'];risk=S['metrics']['cvar95_usd']['mean'];shift=S['metrics']['shifted_IT_mwh']['mean']
guard=G[G.experiment.eq('CdfI3G')].set_index('scenario');projection=G[G.experiment.eq('CdfI3')].set_index('scenario');ramp=guard.loc['ramp25']
